import{_ as r,a0 as s,w as a,s as m,ao as l,I as e,x as n,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux桌面上的小餅餅，讓啓動應用分外不同！ | LCTT x X-CMD","titleTemplate":false,"description":"Linux桌面上的小餅餅，讓啓動應用分外不同！ | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux桌面上的小餅餅，讓啓動應用分外不同！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux桌面上的小餅餅，讓啓動應用分外不同！ | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/How to launch applications differently with Gnome-Pie on Linux desktop","title":"Linux桌面上的小餅餅，讓啓動應用分外不同！","tag":"201406","desc":""},"relativePath":"201406/How to launch applications differently with Gnome-Pie on Linux desktop.md","filePath":"[post].md"}'),u={name:"201406/How to launch applications differently with Gnome-Pie on Linux desktop.md"};function d(f,t,g,x,P,T){const i=s("Link");return a(),m("div",null,[t[15]||(t[15]=l(`<h1 id="linux桌面上的小餅餅-讓啓動應用分外不同" tabindex="-1">Linux桌面上的小餅餅，讓啓動應用分外不同！ <a class="header-anchor" href="#linux桌面上的小餅餅-讓啓動應用分外不同" aria-label="Permalink to “Linux桌面上的小餅餅，讓啓動應用分外不同！”">​</a></h1><p>最近，你能聽到很多關於Ubuntu新的Unity界面的抱怨。我記得，當Unity開始興起的時候，我正好離開Archlinux。然而，Unity間接地導致了一個後果：隨着人們對它不滿意，人們開始關注其他的桌面環境和Linux發行版。而如果你的系統支持Unity，沒有人會反對將它弄得更順眼些。</p><p>所以今天我向你推薦一個絕對原創的程序啓動器： Gnome-Pie。你們可能會認為他的靈感來自魔獸世界插件&quot;OPie&quot;。因為他們有着相似的概念： 鍵盤快捷方式可以打開圓形&quot;菜單&quot;，您可以從中選擇一個應用程序或命令來啓動。這種設計背後的主要思想是用户不必記住命令，但需要記住他的方向和操作。它的餅形設計讓指針可以用同樣的距離啓動每個應用程序。再加上我們還有如此多自定義組合鍵，極大的提高效率並且最大限度地實現了人機工程學。</p><h3 id="安裝gnome-pie" tabindex="-1">安裝Gnome-Pie <a class="header-anchor" href="#安裝gnome-pie" aria-label="Permalink to “安裝Gnome-Pie”">​</a></h3><p>在Ubuntu上，Gnome-Pie 可以從universe倉庫中獲得, 但是，某些原因，這個版本不是很穩定，常常會崩潰。作為一個備選方案，我建議你從官方的源進行下載。</p><pre><code>$ sudo add-apt-repository ppa:simonschneegans/testing
$ sudo apt-get update
$ sudo apt-get install gnome-pie 
</code></pre><p>在Fedora, 你可以使用以下命令：</p><pre><code>$ sudo yum install gnome-pie 
</code></pre>`,8)),e("p",null,[t[1]||(t[1]=n("對於Archlinux, 你可以在",-1)),o(i,{href:"https://aur.archlinux.org/packages/gnome-pie/"},{default:p(()=>[...t[0]||(t[0]=[n("AUR",-1)])]),_:1}),t[2]||(t[2]=n("找到它。",-1))]),t[16]||(t[16]=l('<h3 id="gnome-pie的基本用法" tabindex="-1">Gnome-Pie的基本用法 <a class="header-anchor" href="#gnome-pie的基本用法" aria-label="Permalink to “Gnome-Pie的基本用法”">​</a></h3><p>默認的，Gnome-Pie有一個比較可靠的初始配置。首先，你可以使用 <strong>Ctrl + Alt + a</strong> 調出，它將顯示你的系統的基本應用程序。</p><p><img src="https://farm3.staticflickr.com/2917/14040269128_6dc6544c14_z.jpg" alt=""></p><p>接下來， 按下 <strong>Ctrl+Alt+b</strong> 調出第二個圓，這將顯示你的文件管理器的書籤。</p><p><img src="https://farm3.staticflickr.com/2903/14040269088_8de29edd18.jpg" alt=""></p><p>第三個，也許是最有用的，它會顯示你的應用程序菜單，按下 <strong>Ctrl + Alt + 空格</strong> 可調出。</p><p><img src="https://farm3.staticflickr.com/2903/14040345657_071f40b22f_z.jpg" alt=""></p><p>第四個，僅用於控制音樂播放器。你可以猜到，快捷鍵是 <strong>Ctrl + Alt + m</strong>。</p><p><img src="https://farm3.staticflickr.com/2925/14226915065_8b0e3841c6_o.png" alt=""></p><p>第五個，你可以快速訪問重新啓動、 關機和註銷命令 (<strong>Ctrl + Alt + q</strong>，我猜q是代表退出吧）。</p><p><img src="https://farm3.staticflickr.com/2931/14040303600_5b3a517335_o.png" alt=""></p><p>最後，第六個，你可以用Pie來控制窗口，可以最小化、 規模、 關閉， 等等. 並且，快捷鍵是 <strong>Ctrl+Alt+w</strong>。</p><p><img src="https://farm3.staticflickr.com/2904/14226699514_42d364a4d4_o.png" alt=""></p><p>雖然我發現這種默認設置已經是相當令人滿意，幾乎和預置的啓動器一樣好。然而，如果讓我雞蛋裏找骨頭，我會説一些快捷方式很難用一隻手執行。大多數情況是，我們用兩隻手打開菜單，然後再回到鼠標以選擇該選項。太不爽了。</p><p>然而，我們在用 Linux！誰會在乎默認設置？自定義才是王道。Gnome-Pie將為你提供優良的服務。通過配置，你可以編輯現有的Pie，改變程序圖標，設計自己的Pie，改變主題，甚至將另外一個Pie菜單作為一個子菜單。</p>',15)),e("p",null,[o(i,{href:"https://www.flickr.com/photos/xmodulo/14247093043/"},{default:p(()=>[...t[3]||(t[3]=[e("img",{src:"https://farm6.staticflickr.com/5508/14247093043_1fe1188709_z.jpg",alt:""},null,-1)])]),_:1})]),t[17]||(t[17]=e("p",null,"你甚至可以編輯它來訪問 URL、 自由設置熱鍵、運行你自己的命令。惟一的缺憾可能是它缺少Widgets。",-1)),t[18]||(t[18]=e("p",null,[e("img",{src:"https://farm3.staticflickr.com/2927/14040264609_b7aa66f078_z.jpg",alt:""})],-1)),t[19]||(t[19]=e("p",null,"總之，相較於傳統的基於文本的啓動器，Gnome-Pie是一個相當有吸引力的可視化應用程序。我很喜歡他的自定義鍵盤和鼠標組合鍵，讓我想起了我在War3或者LOL中的神級操作。如果玩家使用這種操作方式，它可以為你帶來方便和高效。如果你想節約桌面空間，我甚至建議你不要將預置的啓動器放到桌面上。總之，我甚至敢説它可以替代Gnome。",-1)),t[20]||(t[20]=e("p",null,"你覺得怎麼樣？你在所有相信世界上有這麼好的東西嗎？或者説，隨着新的Gnome shell出現，Gnome-Pie開始失去競爭力？歡迎評論。",-1)),t[21]||(t[21]=e("hr",null,null,-1)),e("p",null,[t[5]||(t[5]=n("via: ",-1)),o(i,{href:"http://xmodulo.com/2014/05/launch-applications-differently-gnome-pie-linux-desktop.html"},{default:p(()=>[...t[4]||(t[4]=[n("http://xmodulo.com/2014/05/launch-applications-differently-gnome-pie-linux-desktop.html",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=n("譯者：",-1)),o(i,{href:"https://github.com/MikeCoder"},{default:p(()=>[...t[6]||(t[6]=[n("MikeCoder",-1)])]),_:1}),t[9]||(t[9]=n(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=n("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原創翻譯，",-1)),o(i,{href:"http://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[n("Linux中國",-1)])]),_:1}),t[14]||(t[14]=n(" 榮譽推出",-1))])])}const _=r(u,[["render",d]]);export{k as __pageData,_ as default};
